// Split on paragraph boundaries, packing up to ~1200 characters per chunk
// with a 150-character overlap so a fact spanning a boundary is still
// retrievable from at least one chunk.
const body = $('Document In').first().json.body || {};
const text = String(body.text || '');
const source = String(body.source || 'untitled');
const collection = String(body.collection || 'ods_docs');

const MAX = 1200;
const OVERLAP = 150;

const paragraphs = text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
const chunks = [];
let current = '';

for (const paragraph of paragraphs) {
  if (current && current.length + paragraph.length + 2 > MAX) {
    chunks.push(current);
    current = current.slice(Math.max(0, current.length - OVERLAP));
  }
  current = current ? current + '\n\n' + paragraph : paragraph;
  while (current.length > MAX) {
    chunks.push(current.slice(0, MAX));
    current = current.slice(MAX - OVERLAP);
  }
}
if (current.trim()) chunks.push(current);

return chunks.map((chunk, index) => ({
  json: { collection, source, index, text: chunk },
}));

// Pair each embedding with the chunk it came from. Both node outputs are
// in the same order, one item per chunk.
const embeddings = $input.all();
const chunks = $('Chunk Document').all();

if (embeddings.length !== chunks.length) {
  throw new Error(
    `Embedding count ${embeddings.length} does not match chunk count ${chunks.length}`
  );
}

// Deterministic point id: UUIDv5 over "source#index" in the URL namespace,
// so re-ingesting a document overwrites its own points instead of piling up
// duplicates. Implemented inline because the Code node has no uuid import.
const crypto = require('crypto');
const NAMESPACE_URL = '6ba7b811-9dad-11d1-80b4-00c04fd430c8';

function uuidv5(name) {
  const nsBytes = Buffer.from(NAMESPACE_URL.replace(/-/g, ''), 'hex');
  const hash = crypto
    .createHash('sha1')
    .update(Buffer.concat([nsBytes, Buffer.from(name, 'utf8')]))
    .digest();
  const bytes = Buffer.from(hash.subarray(0, 16));
  bytes[6] = (bytes[6] & 0x0f) | 0x50;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = bytes.toString('hex');
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    hex.slice(12, 16),
    hex.slice(16, 20),
    hex.slice(20),
  ].join('-');
}

const points = embeddings.map((item, i) => {
  const vector = item.json?.data?.[0]?.embedding;
  if (!Array.isArray(vector)) {
    throw new Error(`Embedding ${i} has no vector — check the embeddings service`);
  }
  const chunk = chunks[i].json;
  return {
    id: uuidv5(`${chunk.source}#${chunk.index}`),
    vector,
    payload: {
      text: chunk.text,
      source: chunk.source,
      chunk_index: chunk.index,
      ingested_at: new Date().toISOString(),
    },
  };
});

return [{
  json: { collection: chunks[0].json.collection, source: chunks[0].json.source, points },
}];
